  "p{font:600 40px Inter,sans-serif;color:#F7F5F0;text-align:center;margin:0;line-height:1.25;text-shadow:0 2px 12px rgba(10,23,39,.90)}";

var SRCCSS = "html,body{margin:0;padding:0;overflow:hidden}" + FONTS +
  ".src{font:600 34px Inter,sans-serif;color:rgba(247,245,240,.72);text-align:center;border-bottom:2px solid rgba(214,173,98,.42);padding-bottom:10px}";

function esc(s) {
  return String(s == null ? "" : s)
    .split("&").join("&amp;")
    .split("<").join("&lt;")
    .split(">").join("&gt;");
}

if (sahnalar.length === 0) {
