}

var sahnaClips = [];
var GAP = 0.08;

for (var i = 0; i < sahnalar.length; i++) {
  var s   = sahnalar[i];
  var st  = Number(s.start) || 0;
  var ln  = Number(s.length) || 5;

  if (i < sahnalar.length - 1) {
    var nextSt = Number(sahnalar[i + 1].start) || (st + ln);
    if (st + ln > nextSt - GAP) { ln = nextSt - GAP - st; }
  }
  if (ln < 0.5) { ln = 0.5; }
  if (st + ln > dur) { ln = Math.max(0.5, dur - st); }

  var tur = String(s.tur || "text");
  var h   = "";

  if (tur === "peak") {
    h = '<div class="s pk"><div class="num">' + esc(s.raqam) + '</div>' +
        (s.kontekst1 ? '<div class="c1">' + esc(s.kontekst1) + '</div>' : '') +
