  } else if (tur === "stat-pair") {
    h = '<div class="s">' +
        (s.raqam2 ? '<div class="num2">' + esc(s.raqam2) + '</div>' : '') +
        '<div class="num">' + esc(s.raqam) + '</div>' +
        (s.kontekst1 ? '<div class="c1">' + esc(s.kontekst1) + '</div>' : '') +
        '</div>';
  } else if (tur === "text") {
    h = '<div class="s">' +
        (s.kontekst1 ? '<div class="c1">' + esc(s.kontekst1) + '</div>' : '') +
        (s.kontekst2 ? '<div class="c2">' + esc(s.kontekst2) + '</div>' : '') +
        '</div>';
  } else {
    h = '<div class="s"><div class="num">' + esc(s.raqam) + '</div>' +
        (s.kontekst1 ? '<div class="c1">' + esc(s.kontekst1) + '</div>' : '') +
        (s.kontekst2 ? '<div class="c2">' + esc(s.kontekst2) + '</div>' : '') +
        '</div>';
  }

  sahnaClips.push({
    asset: { type: "html5", html: h, css: SCSS },
    width: 1280,
    height: 720,
    start: st,
    length: ln,
    position: "center"
  });
}

var subClips = [];

if (align && align.characters && align.characters.length) {
  var ch = align.characters;
  var ts = align.character_start_times_seconds || [];
  var te = align.character_end_times_seconds || [];

  var MAXCH = 70;
  var blocks = [];
  var cur = "", curStart = null, curEnd = 0;

  for (var k = 0; k < ch.length; k++) {
    if (curStart === null) { curStart = Number(ts[k]) || 0; }
    cur += ch[k];
    curEnd = Number(te[k]) || curStart;

    var c = ch[k];
    var endsSentence = (c === "." || c === "!" || c === "?");
    var endsClause   = (c === "," || c === ":" || c === ";");
    var tooLong      = (cur.length >= MAXCH * 2) && (ch[k] === " ");

    if (endsSentence || (endsClause && cur.length > MAXCH) || tooLong) {
      var txt = cur.trim();
      if (txt.length > 0) { blocks.push({ t: txt, s: curStart, e: curEnd }); }
      cur = ""; curStart = null;
    }
  }
  if (cur.trim().length > 0) {
    blocks.push({ t: cur.trim(), s: curStart || 0, e: curEnd });
  }

  for (var b = 0; b < blocks.length; b++) {
    if (b < blocks.length - 1) {
      if (blocks[b].e > blocks[b + 1].s - GAP) { blocks[b].e = blocks[b + 1].s - GAP; }
    }
    if (blocks[b].e - blocks[b].s < 0.6) { blocks[b].e = blocks[b].s + 0.6; }
  }

  for (var m = 0; m < blocks.length; m++) {
    var bl = blocks[m];
    var L = bl.e - bl.s;
    if (L < 0.4) { continue; }
    if (bl.s + L > dur) { L = Math.max(0.4, dur - bl.s); }
    subClips.push({
      asset: { type: "html5", html: "<p>" + esc(bl.t) + "</p>", css: SUBCSS },
      width: 1100,
      height: 150,
      start: bl.s,
      length: L,
      position: "bottom",
      offset: { y: 0.10 }
    });
  }
}

